function graphUrl(path, version2, query) {
  if (!path.startsWith("/") || path.startsWith("//"))
    throw new Error("path must start with a single '/'.");
  const url2 = new URL(`${version2 === "beta" ? GRAPH_BETA_BASE : GRAPH_BASE}${path}`);
  if (url2.origin !== "https://graph.microsoft.com")
    throw new Error("path must stay on graph.microsoft.com.");
  for (const [k2, v2] of Object.entries(query ?? {}))
    url2.searchParams.set(k2, v2);
  return url2;
}
async function graphList(path, filter, top, select) {
  const url2 = new URL(`${GRAPH_BASE}${path}`);
  url2.searchParams.set("$top", String(Math.min(Math.max(top ?? 50, 1), 999)));
  url2.searchParams.set("$select", select);
  if (filter)
    url2.searchParams.set("$filter", filter);
  const headers = filter ? { ConsistencyLevel: "eventual" } : void 0;
  return collectPaged(url2.toString(), GRAPH_RESOURCE, headers);
}
var listSchema = (filterHint) => ({
  filter: external_exports.string().optional().describe(filterHint),
  top: external_exports.number().optional().describe("Page size, 1-999. Default 50.")
});
