// dist/server.js
var LOGO_FILE = "azure-512.png";
var LOGO_MIME_TYPE = "image/png";
var LOGO_URI = "azure://assets/logo.png";
var moduleDir = dirname2(fileURLToPath(import.meta.url));
var logoPath = join2(moduleDir, "..", "assets", LOGO_FILE);
var logoBase64 = existsSync2(logoPath) ? readFileSync(logoPath).toString("base64") : void 0;
function createServer() {
  const server = new McpServer({
    name: SERVER_NAME,
    title: SERVER_NAME,
    version: SERVER_VERSION,
    icons: logoBase64 ? [{ src: `data:${LOGO_MIME_TYPE};base64,${logoBase64}`, mimeType: LOGO_MIME_TYPE, sizes: ["512x512"] }] : []
  }, { instructions: SERVER_INSTRUCTIONS });
  registerCoreTools(server);
  registerListTools(server);
  registerComputeTools(server);
  registerGovernanceTools(server);
  registerScopedTools(server);
  registerKeyVaultTools(server);
  registerGraphTools(server);
  registerMonitorTools(server);
  registerCliTools(server);
  registerAppViews(server);
  if (logoBase64) {
    server.registerResource("azure_logo", LOGO_URI, { title: "Azure Logo", description: "Microsoft Azure logo packaged with the MCP server.", mimeType: LOGO_MIME_TYPE }, async (uri) => ({ contents: [{ uri: uri.href, mimeType: LOGO_MIME_TYPE, blob: logoBase64 }] }));
  }
  server.registerResource("api_reference", "azure://reference/api", { title: "Azure API Reference", description: "Every tool with its tier, HTTP method, path template, api-version and Azure CLI equivalent.", mimeType: "application/json" }, async (uri) => ({
    contents: [
      {
        uri: uri.href,
        mimeType: "application/json",
        text: JSON.stringify({ server: SERVER_NAME, version: SERVER_VERSION, auth_mode: authMode(), arm_base: ARM_BASE, tools: apiReference() }, null, 2)
      }
    ]
  }));
  return server;
}

// dist/index.js
async function main() {
  const server = createServer();
  await server.connect(new StdioServerTransport());
  const auth = BASE_AUTH_MODE === "azure_cli" ? `azure cli via ${AZ_LABEL}` : BASE_AUTH_MODE.replace("_", " ");
  const gate = isWriteMode() ? isDestructiveAllowed() ? "write+destructive" : "write" : "read";
  console.error(`Azure MCP server running on stdio (auth: ${auth}, mode: ${gate})`);
}
main().catch((error62) => {
  const details = error62 instanceof ArmApiError ? { message: error62.message, status: error62.status, statusText: error62.statusText, details: error62.details } : { message: error62 instanceof Error ? error62.message : String(error62) };
  console.error(JSON.stringify(details, null, 2));
  process.exit(1);
});
